package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.PolicyUriVO;

class PolicyUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of policy uri of oauth client")
  void test_policy_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    PolicyUriValueHolder<Object> value = new PolicyUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.policyUri("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPolicyUriValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPolicyUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.policyUriNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPolicyUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPolicyUri().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of policy uri of oauth client")
  void test_policy_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    PolicyUriValueHolder<Object> value = new PolicyUriValueHolder<>(holder);
    PolicyUriVO vo = PolicyUriVO.from("one");
    Assertions.assertFalse(value.getPolicyUriValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.policyUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPolicyUriValue().orElseThrow());
    Assertions.assertSame(holder, value.policyUri(Optional.empty()));
    Assertions.assertFalse(value.getPolicyUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.policyUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPolicyUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of policy uri of oauth client against the original")
  void test_policy_uri_value_holder_read() {
    Object holder = new Object();
    PolicyUriValueHolder<Object> value = new PolicyUriValueHolder<>(holder);
    PolicyUriVO vo = PolicyUriVO.from("one");
    PolicyUriVO other = PolicyUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getPolicyUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPolicyUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPolicyUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.policyUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPolicyUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPolicyUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of policy uri of oauth client")
  void test_policy_uri_value_holder_unset() {
    Object holder = new Object();
    PolicyUriValueHolder<Object> value = new PolicyUriValueHolder<>(holder);
    PolicyUriVO vo = PolicyUriVO.from("one");
    value.policyUri(vo);
    Assertions.assertSame(holder, value.unsetPolicyUriIfMatches("policyUri_other"));
    Assertions.assertTrue(value.getPolicyUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPolicyUriIfMatches("policyUri"));
    Assertions.assertFalse(value.getPolicyUriValue().isPresent(),
        "The field name must clear the value");
    value.policyUri(vo);
    Assertions.assertSame(holder, value.unsetPolicyUri());
    Assertions.assertFalse(value.getPolicyUriValue().isPresent(), "Unset must clear the value");
  }
}
